<script>
const upload=document.getElementById('image-upload'); upload?.addEventListener('change',()=>{const preview=document.getElementById('image-preview'); preview.innerHTML=''; [...upload.files].forEach(file=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4194304)return; const img=document.createElement('img'); img.className='rounded'; img.style='width:96px;height:96px;object-fit:contain'; img.alt=file.name; img.src=URL.createObjectURL(file); preview.appendChild(img);});});
const list=document.getElementById('image-list'); if(list){let dragged; list.querySelectorAll('.image-card').forEach(card=>{card.addEventListener('dragstart',()=>dragged=card);card.addEventListener('dragover',event=>event.preventDefault());card.addEventListener('drop',event=>{event.preventDefault();if(dragged&&dragged!==card){const cards=[...list.children];list.insertBefore(dragged,cards.indexOf(dragged)<cards.indexOf(card)?card:card.nextSibling);}});});}
</script>
